/**
 * KALLAYI CAR SPA & AUTO CARE - STAFF ONBOARDING & AUTHENTICATION VERIFICATION
 * 
 * Verifies:
 * 1. Admin staff creation provisions GoTrue user with role 'STAFF' and autogenerated 'CarSpa@[Last4Digits]' password.
 * 2. Database staff_profiles record is linked to auth user_id.
 * 3. Worker login via POST /api/auth/login strictly resolves role 'STAFF' and redirect '/staff/queue'.
 * 4. Auth profile check via GET /api/auth/me returns role 'STAFF' and is_staff: true.
 * 5. Customer signup with staff phone number auto-elevates to 'STAFF' and routes to '/staff/queue'.
 * 6. Clean teardown of test fixtures.
 */

import { createClient } from '@supabase/supabase-js';
import * as fs from 'fs';

const env = fs.readFileSync('.env.local', 'utf8');
const url = env.split('\n').find(l => l.startsWith('NEXT_PUBLIC_SUPABASE_URL='))?.split('=')[1]?.trim()?.replace(/['"]/g, '');
const key = env.split('\n').find(l => l.startsWith('SUPABASE_SERVICE_ROLE_KEY='))?.split('=')[1]?.trim()?.replace(/['"]/g, '');

const supabase = createClient(url, key);

const BASE_URL = 'http://localhost:3000';
const TEST_PHONE = '9847099991';
const NORMALIZED_PHONE = '+919847099991';
const EXPECTED_PASSWORD = 'CarSpa@9991';

async function runVerification() {
  console.log('================================================================');
  console.log(' Starting Staff Onboarding & Authentication Flow Verification');
  console.log('================================================================\n');

  try {
    // 0. Pre-clean existing test records
    console.log('[Step 0] Cleaning up any prior test records...');
    const { data: oldStaff } = await supabase
      .from('staff_profiles')
      .select('id, user_id')
      .eq('phone_number', NORMALIZED_PHONE);

    for (const s of (oldStaff || [])) {
      if (s.user_id) {
        try { await supabase.auth.admin.deleteUser(s.user_id); } catch {}
      }
      await supabase.from('staff_profiles').delete().eq('id', s.id);
    }

    // Also clean up by candidate emails
    const candidateEmails = ['9847099991@kallayi.internal', '919847099991@kallayi.internal'];
    for (const em of candidateEmails) {
      try {
        const { data: linkData } = await supabase.auth.admin.generateLink({ type: 'magiclink', email: em });
        if (linkData?.user?.id) {
          await supabase.auth.admin.deleteUser(linkData.user.id);
        }
      } catch {}
    }
    console.log('✓ Clean state prepared.\n');

    // 1. Admin Staff Creation via POST /api/staff/directory
    console.log('[Step 1] Testing Admin Staff Creation via POST /api/staff/directory...');
    const registerRes = await fetch(`${BASE_URL}/api/staff/directory`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: 'AutoTest Worker',
        first_name: 'AutoTest',
        phone_number: NORMALIZED_PHONE,
        role: 'WASHER',
        salary_type: 'DAILY',
        salary_amount: 750,
        commission_rate: 40,
        // no password provided -> should auto-generate CarSpa@9991
      }),
    });

    const registerData = await registerRes.json();
    console.log('API Response Status:', registerRes.status);
    console.log('API Response Data:', {
      success: registerData.success,
      default_password: registerData.data?.default_password,
      role: registerData.data?.role,
      user_id: registerData.data?.user_id,
      phone_number: registerData.data?.phone_number,
    });

    if (!registerData.success) {
      throw new Error(`Staff creation failed: ${registerData.error}`);
    }
    if (registerData.data?.default_password !== EXPECTED_PASSWORD) {
      throw new Error(`Expected password '${EXPECTED_PASSWORD}', got '${registerData.data?.default_password}'`);
    }
    console.log('✓ Admin creation succeeded with autogenerated password CarSpa@9991.\n');

    // 2. Verify Supabase GoTrue Auth User
    console.log('[Step 2] Verifying Supabase GoTrue Auth User Provisioning...');
    const authUserId = registerData.data?.user_id;
    const { data: authUserRecord, error: authErr } = await supabase.auth.admin.getUserById(authUserId);

    if (authErr || !authUserRecord?.user) {
      throw new Error(`Failed to find GoTrue auth user: ${authErr?.message}`);
    }

    const authMeta = authUserRecord.user.user_metadata;
    console.log('GoTrue User Data:', {
      id: authUserRecord.user.id,
      phone: authUserRecord.user.phone,
      email: authUserRecord.user.email,
      role: authMeta?.role,
      staff_role: authMeta?.staff_role,
    });

    if (authMeta?.role !== 'STAFF') {
      throw new Error(`Expected user_metadata.role to be 'STAFF', got '${authMeta?.role}'`);
    }
    console.log('✓ GoTrue user strictly provisioned with role: STAFF.\n');

    // 3. Verify Database staff_profiles linking
    console.log('[Step 3] Verifying public.staff_profiles Linking...');
    const { data: dbStaff, error: dbErr } = await supabase
      .from('staff_profiles')
      .select('*')
      .eq('id', registerData.data?.id)
      .single();

    if (dbErr || !dbStaff) {
      throw new Error(`Failed to query staff_profiles: ${dbErr?.message}`);
    }

    if (dbStaff.user_id !== authUserId) {
      throw new Error(`staff_profiles.user_id '${dbStaff.user_id}' does not match authUserId '${authUserId}'`);
    }
    console.log('✓ Database staff profile correctly linked to GoTrue auth user_id.\n');

    // 4. Test Login via POST /api/auth/login
    console.log('[Step 4] Testing Worker Login via POST /api/auth/login...');
    const loginRes = await fetch(`${BASE_URL}/api/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        phone: TEST_PHONE,
        password: EXPECTED_PASSWORD,
      }),
    });

    const loginData = await loginRes.json();
    console.log('Login Status:', loginRes.status);
    console.log('Login Response:', {
      success: loginData.success,
      role: loginData.user?.role,
      is_staff: loginData.user?.is_staff,
      redirect: loginData.redirect,
    });

    if (!loginData.success) {
      throw new Error(`Login failed: ${loginData.message || loginData.error}`);
    }
    if (loginData.user?.role !== 'STAFF') {
      throw new Error(`Expected login role 'STAFF', got '${loginData.user?.role}'`);
    }
    if (!loginData.user?.is_staff) {
      throw new Error(`Expected login is_staff to be true, got '${loginData.user?.is_staff}'`);
    }
    if (loginData.redirect !== '/staff/queue') {
      throw new Error(`Expected redirect '/staff/queue', got '${loginData.redirect}'`);
    }
    console.log('✓ Login verified: Role is STAFF and redirect is strictly /staff/queue.\n');

    // 5. Test Current User Profile via GET /api/auth/me
    console.log('[Step 5] Testing Profile Verification via GET /api/auth/me...');
    const sessionToken = loginData.token;
    const meRes = await fetch(`${BASE_URL}/api/auth/me`, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${sessionToken}`,
      },
    });

    const meData = await meRes.json();
    console.log('Auth Me Status:', meRes.status);
    console.log('Auth Me Data:', {
      id: meData.id,
      role: meData.role,
      is_staff: meData.is_staff,
      phone: meData.phone,
    });

    if (meData.role !== 'STAFF') {
      throw new Error(`Expected /api/auth/me role 'STAFF', got '${meData.role}'`);
    }
    if (!meData.is_staff) {
      throw new Error(`Expected /api/auth/me is_staff to be true, got '${meData.is_staff}'`);
    }
    console.log('✓ /api/auth/me verified: Authenticated session resolves strictly to STAFF.\n');

    // 6. Test Customer Signup Interception
    console.log('[Step 6] Testing Customer Signup Interception for Registered Staff Phone...');
    // If worker enters /signup with their phone
    const signupRes = await fetch(`${BASE_URL}/api/customers/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: 'AutoTest Worker',
        phone: TEST_PHONE,
        password: 'NewPassword@2026',
      }),
    });

    const signupData = await signupRes.json();
    console.log('Signup Interception Status:', signupRes.status);
    console.log('Signup Interception Data:', {
      success: signupData.success,
      role: signupData.user?.role,
      redirect: signupData.redirect,
    });

    if (!signupData.success) {
      throw new Error(`Signup interception failed: ${signupData.error}`);
    }
    if (signupData.user?.role !== 'STAFF') {
      throw new Error(`Expected signup role 'STAFF', got '${signupData.user?.role}'`);
    }
    if (signupData.redirect !== '/staff/queue') {
      throw new Error(`Expected redirect '/staff/queue', got '${signupData.redirect}'`);
    }
    console.log('✓ Customer signup intercept verified: Staff phone is elevated to STAFF and routed to /staff/queue.\n');

    // 7. Cleanup Test Fixtures
    console.log('[Step 7] Cleaning up test fixtures...');
    try {
      if (authUserId) {
        await supabase.auth.admin.deleteUser(authUserId);
      }
      await supabase.from('staff_profiles').delete().eq('phone_number', NORMALIZED_PHONE);
    } catch (cleanErr) {
      console.warn('Cleanup warning:', cleanErr);
    }
    console.log('✓ Test fixtures successfully removed.\n');

    console.log('================================================================');
    console.log(' 🎉 ALL STAFF ONBOARDING & AUTHENTICATION TESTS PASSED 100%! ');
    console.log('================================================================\n');
  } catch (error) {
    console.error('\n❌ Verification Failed:', error);
    // Cleanup on failure
    try {
      await supabase.from('staff_profiles').delete().eq('phone_number', NORMALIZED_PHONE);
    } catch {}
    process.exit(1);
  }
}

runVerification();
